import React from 'react';

const Projects = () => {
  const projects = [
    {
      title: '🎮 Snake Game',
      description: 'Classic Snake game in C++ (SFML) with smooth gameplay',
      tech: ['C++', 'SFML'],
      github: 'https://github.com/Cluster3824'
    },
    {
      title: '🧾 HSN Code LLM Agent',
      description: 'AI-powered HSN Code Validation & Suggestion using Google ADK, Ollama (llama3.2), LiteLLM, Pandas',
      tech: ['Google ADK', 'Ollama', 'LiteLLM', 'Pandas', 'Python'],
      github: 'https://github.com/Cluster3824'
    },
    {
      title: '📂 PDF & CSV Reader',
      description: 'File reader for data analysis & quick insights',
      tech: ['Python', 'Pandas'],
      github: 'https://github.com/Cluster3824'
    },
    {
      title: '🌐 Hybrid Research Agent',
      description: 'Chatbot that fetches real-time info from Google, Reddit, and Wikipedia with LLM-powered reasoning',
      tech: ['LangChain', 'Python', 'APIs'],
      github: 'https://github.com/Cluster3824'
    }
  ];

  return (
    <section id="projects" className="projects">
      <div className="container">
        <h2>Featured Projects</h2>
        <div className="projects-grid">
          {projects.map((project, index) => (
            <div key={index} className="project-card">
              <h3>{project.title}</h3>
              <p>{project.description}</p>
              <div className="project-tech">
                {project.tech.map((tech, techIndex) => (
                  <span key={techIndex}>{tech}</span>
                ))}
              </div>
              <div className="project-links">
                <a href={project.github} target="_blank" rel="noopener noreferrer">
                  <i className="fab fa-github"></i> Code
                </a>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Projects;
